/* --------------------------------------------------------------------------
   1b. Reporting line back-fill

   manager_id is derived by a trigger from the payload, so it can only resolve once
   both people exist. This second pass fixes the reports whose manager was created
   after them.
   -------------------------------------------------------------------------- */

update public.people set legacy_payload = legacy_payload
 where legacy_payload->>'demoDataSet' = 'STAGE-14A'
   and coalesce(btrim(legacy_payload->>'managerResourceId'), '') <> ''
   and manager_id is null;

/* --------------------------------------------------------------------------
   2. Portfolio and programmes

   The existing portfolio and five programmes are filled in rather than replaced.
   They were created as near-empty shells, which makes the programme pages look
   broken; this gives them dates, budgets, objectives, sponsors and commentary.
   
   coalesce is used throughout so anything already set by hand is preserved.
   -------------------------------------------------------------------------- */

update public.portfolios set
    description = coalesce(nullif(description, ''), 'All change activity across the organisation, grouped into five programmes and governed through a single portfolio board.'),
    status = coalesce(nullif(status, ''), 'Active'),
    budget = case when coalesce(budget, 0) = 0 then 12070000 else budget end,
    currency = coalesce(nullif(currency, ''), 'GBP'),
    default_reporting_frequency = coalesce(nullif(default_reporting_frequency, ''), 'Monthly'),
    owner_id = coalesce(owner_id, (select id from public.people where legacy_resource_id = 'RES-0101')),
    executive_sponsor_id = coalesce(executive_sponsor_id, (select id from public.people where legacy_resource_id = 'RES-0102')),
    legacy_payload = public.portfolios.legacy_payload || $ppm${"portfolioId":"PORT-00001","name":"Portfolio Manager","portfolioCode":"PORT-00001","description":"All change activity across the organisation, grouped into five programmes and governed through a single portfolio board.","status":"Active","budget":12070000,"currency":"GBP","financialYear":"2026/27","financialYearStartMonth":4,"defaultReportingFrequency":"Monthly","ownerResourceId":"RES-0101","executiveSponsorResourceId":"RES-0102","reportingCalendarId":"CAL-00001","active":true,"demoDataSet":"STAGE-14A"}$ppm$::jsonb
where portfolio_code = 'PORT-00001';

