    overall_rag = case when coalesce(overall_rag, 'Not Assessed') in ('', 'Not Assessed') then 'Amber' else overall_rag end,
    strategic_objective = coalesce(nullif(strategic_objective, ''), 'Reduce cost to serve and improve member satisfaction by moving routine servicing to self-service without losing the option to speak to a person.'),
