select 'PRJ-00008', 'Contact Centre Workforce Management', 'Introduction of a workforce management tool for the servicing contact centre, covering forecasting, scheduling, intraday management and adherence reporting.', 'Medium', 'Active', 'Requirements and Design', 'Build', 'Amber', 'Medium', '2026-04-06', '2027-01-29', '2026-04-20', '2027-02-26', '2027-01-25', 24, 'Requirements are 80% signed off. Vendor selection is complete with a preferred supplier, but contract negotiation is taking longer than planned over data processing terms.', 'Close the data processing schedule with Legal and the DPO, complete the remaining requirements sign-off, and hold the design gate on 16 October.', 'Demand forecasting, shift scheduling, intraday reforecasting, adherence and shrinkage reporting, holiday and absence integration with the HR system, and agent self-service shift swaps.', 'Payroll integration, performance management, quality monitoring, and any team outside the servicing contact centre.', 'Start was two weeks late waiting for the vendor shortlist, and contract negotiation on data processing terms has added a further four weeks.', 'Legal has committed to a final position by 2 October. If contract signature lands in October the four-week slippage is absorbed in the build phase float and the project returns to Green at the design gate.', 'Amber', 'Amber', 'Green', 'Amber', 'Green', false,
    (select id from public.programmes where programme_code = 'PRG-00001'),
    (select id from public.people where legacy_resource_id = 'RES-0106'),
    (select id from public.people where legacy_resource_id = 'RES-0111'),
    (select id from public.people where legacy_resource_id = 'RES-0110'),
    $ppm${"shortName":"WFM","formerName":"","projectClassification":"Change","confidentialityClassification":"Internal","portfolioId":"PORT-00001","portfolio":"Portfolio Manager","lifecycleTemplateId":"LIFE-00001","lifecycleTemplateVersion":1,"reportingCalendarId":"CAL-00001","approvalStatus":"Approved","sponsorConfirmationStatus":"Confirmed","requirementsApprovalStatus":"Not started","baselineApprovalStatus":"Not started","goLiveApprovalStatus":"Not started","closureApprovalStatus":"Not started","operationalReadinessStatus":"Not started","trainingStatus":"Not started","communicationsStatus":"Not started","testDatesStatus":"Not started","reportingFrequency":"Monthly","archived":false,"archivedAt":"","archiveReason":"","preArchiveStatus":"","stageOverrideReason":"","reasonForSlippage":"Start was two weeks late waiting for the vendor shortlist, and contract negotiation on data processing terms has added a further four weeks.","returnToGreen":"Legal has committed to a final position by 2 October. If contract signature lands in October the four-week slippage is absorbed in the build phase float and the project returns to Green at the design gate.","actualStartDate":"2026-04-20","actualEndDate":"","closureDate":"","approvedImplementationDate":"","indicativeCosts":350000,"costEstimate":385000,"benefitRag":"Green","qualityRag":"Not Assessed","operationalReadinessRag":"Not Assessed","calculatedRags":{},"ragOverrideJustifications":{},"defectsBlockers":"","deploymentDependencies":"","goLiveCriteria":"","supportModel":"","hypercarePlan":"","rollbackPlan":"","outstandingRisksIssues":"","closureSummary":"","finalFinancialPosition":"","outstandingActions":"","benefitsHandover":"","lessonsLearned":"","archiveLocation":"","solutionOptions":"Packaged workforce management software, a module from the telephony vendor, or improving the spreadsheet process. Packaged software was chosen for forecasting capability the telephony module lacks.","operationalReadinessRequirements":"Team leader training on forecasting, agent training on shift self-service, staff forum consultation complete, and a documented fallback to spreadsheet scheduling.","testApproach":"Vendor-supported configuration testing, an integration test of the HR absence feed, and a four-week parallel run against the current spreadsheets before any team relies on it.","implementationApproach":"Team by team over four weeks, with the spreadsheet kept as fallback.","discoveryDeliverables":"Current-state scheduling assessment, requirements catalogue, vendor long list and evaluation criteria, and a benefits case.","deliveryPlanSummary":"Configure and integrate through the autumn, parallel run one team from November, phased rollout by team through January, live for the 2027 ISA season.","detailedResourceDemand":"One business analyst, one integration developer, a part-time change lead, and two team leaders at 50% through configuration and parallel running.","resourceDemandSummary":"Peak demand 3.6 FTE in November 2026.","initialResourceRequirements":"Estimated 3 to 4 FTE plus vendor professional services.","initialRaidSummary":"Staff engagement with scheduling change, HR integration feasibility, and vendor lock-in were raised at intake.","assumptionsConstraints":"Assumes the HR system can provide an absence feed. Constrained by the ISA season freeze and by a commitment to the staff forum that no scheduling change lands before April.","strategicDependencies":"None outside the programme.","deliveryDependencies":"Vendor contract signature; HR system absence API; telephony platform historical call data extract.","successMeasures":"Forecast accuracy, schedule adherence, service level at peak, team leader time on scheduling, and overtime spend.","benefitMeasures":"Workforce management tool reporting alongside the payroll overtime line.","expectedBenefits":"Recovery of about 150 team leader days a year, a 4 point improvement in service level at peak, and reduction in overtime spend of around £48,000 a year.","customerOutcome":"More consistent call answering times, particularly at peak.","regulatoryDriver":"","mandatoryDeliveryDate":"","nextStageGateDate":"2026-10-16","currentStageGate":"Gate 2 - Requirements in progress","requestor":"Helen Marsh","requestorResourceId":"RES-0110","requestorEmail":"helen.marsh@example.com","projectManager":"Greg Sanderson","projectManagerResourceId":"RES-0106","projectManagerEmail":"greg.sanderson@example.com","sponsor":"Owen Pritchard","sponsorResourceId":"RES-0111","sponsorEmail":"owen.pritchard@example.com","projectLead":"Helen Marsh","projectLeadResourceId":"RES-0110","projectLeadEmail":"helen.marsh@example.com","deputyProjectManager":"","deputyProjectManagerResourceId":"","deputyProjectManagerEmail":"","businessOwner":"Helen Marsh","businessOwnerResourceId":"RES-0110","businessOwnerEmail":"helen.marsh@example.com","technicalLead":"Stephen Nkemelu","technicalLeadResourceId":"RES-0109","technicalLeadEmail":"stephen.nkemelu@example.com","businessAnalyst":"Joseph Adeyemi","businessAnalystResourceId":"RES-0113","businessAnalystEmail":"joseph.adeyemi@example.com","testLead":"","testLeadResourceId":"","testLeadEmail":"","changeLead":"Dominic Fry","changeLeadResourceId":"RES-0120","changeLeadEmail":"dominic.fry@example.com","financeContact":"Martin Cole","financeContactResourceId":"RES-0115","financeContactEmail":"martin.cole@example.com","complianceContact":"","complianceContactResourceId":"","complianceContactEmail":"","benefitOwner":"Helen Marsh","benefitOwnerResourceId":"RES-0110","benefitOwnerEmail":"helen.marsh@example.com","projectCode":"PRJ-00008","projectName":"Contact Centre Workforce Management","description":"Introduction of a workforce management tool for the servicing contact centre, covering forecasting, scheduling, intraday management and adherence reporting.","programmeId":"PRG-00001","programme":"Servicing","workstream":"Servicing","businessArea":"Servicing","projectType":"Change project","priority":"Medium","projectStatus":"Active","currentStage":"Requirements and Design","nextStage":"Build","overallRag":"Amber","scheduleRag":"Amber","scopeRag":"Amber","financialRag":"Green","resourceRag":"Amber","riskRag":"Green","deliveryConfidence":"Medium","baselineStartDate":"2026-04-06","baselineEndDate":"2027-01-29","forecastStartDate":"2026-04-20","forecastEndDate":"2027-02-26","targetImplementationDate":"2027-01-25","percentageComplete":24,"dateLogged":"2026-01-19","proposedStartDate":"2026-04-06","currentPosition":"Requirements are 80% signed off. Vendor selection is complete with a preferred supplier, but contract negotiation is taking longer than planned over data processing terms.","nextSteps":"Close the data processing schedule with Legal and the DPO, complete the remaining requirements sign-off, and hold the design gate on 16 October.","highLevelScope":"Demand forecasting, shift scheduling, intraday reforecasting, adherence and shrinkage reporting, holiday and absence integration with the HR system, and agent self-service shift swaps.","outOfScope":"Payroll integration, performance management, quality monitoring, and any team outside the servicing contact centre.","inScope":"The 94 FTE servicing contact centre across two sites and homeworkers.","businessProblem":"Scheduling is done in spreadsheets by two team leaders, takes about three days a fortnight, and cannot reforecast intraday. Adherence is not measured, and the ISA season peak is staffed on judgement rather than forecast.","desiredOutcome":"Forecast-driven scheduling with measured adherence, team leader time returned to coaching, and service levels held through the seasonal peak.","businessPriority":"Medium","strategicDriver":"Improve operational efficiency and service level consistency","strategicObjective":"Reduce cost to serve","additionalStakeholders":"HR, Legal, Data Protection Officer, the two contact centre site managers, and the staff forum.","fundingSource":"Change budget 2026/27","demoDataSet":"STAGE-14A"}$ppm$: