    (select id from public.people where legacy_resource_id = 'RES-0112'),
    $ppm${"shortName":"Adviser Portal","formerName":"","projectClassification":"Change","confidentialityClassification":"Internal","portfolioId":"PORT-00001","portfolio":"Portfolio Manager","lifecycleTemplateId":"LIFE-00001","lifecycleTemplateVersion":1,"reportingCalendarId":"CAL-00001","approvalStatus":"Approved","sponsorConfirmationStatus":"Confirmed","requirementsApprovalStatus":"Not started","baselineApprovalStatus":"Not started","goLiveApprovalStatus":"Not started","closureApprovalStatus":"Not started","operationalReadinessStatus":"Not started","trainingStatus":"Not started","communicationsStatus":"Not started","testDatesStatus":"Not started","reportingFrequency":"Monthly","archived":false,"archivedAt":"","archiveReason":"","preArchiveStatus":"","stageOverrideReason":"","reasonForSlippage":"","returnToGreen":"","actualStartDate":"2026-03-02","actualEndDate":"","closureDate":"","approvedImplementationDate":"2026-09-28","indicativeCosts":600000,"costEstimate":620000,"benefitRag":"Green","qualityRag":"Green","operationalReadinessRag":"Green","calculatedRags":{},"ragOverrideJustifications":{},"defectsBlockers":"","deploymentDependencies":"","goLiveCriteria":"Pilot changes closed, security findings resolved, new business team trained, and support route live.","supportModel":"Intermediary sales managers are first line; digital team second line for eight weeks after each wave.","hypercarePlan":"Weekly adviser feedback calls through November, then into standard support.","rollbackPlan":"Firms can be reverted to paper submission individually at any point.","outstandingRisksIssues":"Adoption risk remains for the eight smallest firms, which have low digital maturity. Risk RAG is Amber for that reason.","closureSummary":"","finalFinancialPosition":"","outstandingActions":"","benefitsHandover":"","lessonsLearned":"","archiveLocation":"","solutionOptions":"Build on the existing web platform, buy an adviser extranet product, or extend the new business system's own portal. Build was chosen because the commission views required are specific to the society.","operationalReadinessRequirements":"New business team trained, adviser onboarding pack and webinars ready, support route agreed with the intermediary sales team, and paper fallback retained.","testApproach":"Automated regression on submission journeys, an eight-week live pilot with two firms, and an external security test before firm enablement.","implementationApproach":"Enable firms in four weekly waves, largest firms last, with paper submission available throughout.","discoveryDeliverables":"Adviser research findings, journey designs, technical approach, and a phased scope recommendation.","deliveryPlanSummary":"Build March to July, pilot with two firms August to September, phased rollout of the remaining firms through October.","detailedResourceDemand":"Three developers, one business analyst, one tester and a part-time change lead, reducing to one developer in hypercare.","resourceDemandSummary":"Peak demand 6.2 FTE in June 2026, now tapering.","initialResourceRequirements":"Estimated 5 to 6 FTE.","initialRaidSummary":"Adviser adoption, commission calculation accuracy, and security of firm-level data access were raised at intake.","assumptionsConstraints":"Assumes firms will adopt without financial incentive, which the pilot supports. Constrained by the requirement that paper submission remains available throughout phase one.","strategicDependencies":"Depends on PRJ-00016 for adviser multi-factor authentication.","deliveryDependencies":"New business system API; agency register data cleanse; commission calculation engine access.","successMeasures":"Portal submission share of intermediated new business, firm onboarding elapsed time, rekeying volume, and adviser satisfaction.","benefitMeasures":"New business system channel reporting and the agency onboarding log.","expectedBenefits":"18% uplift in completed applications through the intermediated channel, onboarding time from 15 to 5 days, and removal of about 6,000 rekeyed applications a year.","customerOutcome":"Faster application turnaround for members whose adviser submits through the portal.","regulatoryDriver":"","mandatoryDeliveryDate":"","nextStageGateDate":"2026-10-30","currentStageGate":"Gate 5 - Go-live approved","requestor":"Nadia Kaur","requestorResourceId":"RES-0112","requestorEmail":"nadia.kaur@example.com","projectManager":"Tom Bradshaw","projectManagerResourceId":"RES-0104","projectManagerEmail":"tom.bradshaw@example.com","sponsor":"Nadia Kaur","sponsorResourceId":"RES-0112","sponsorEmail":"nadia.kaur@example.com","projectLead":"Nadia Kaur","projectLeadResourceId":"RES-0112","projectLeadEmail":"nadia.kaur@example.com","deputyProjectManager":"","deputyProjectManagerResourceId":"","deputyProjectManagerEmail":"","businessOwner":"Nadia Kaur","businessOwnerResourceId":"RES-0112","businessOwnerEmail":"nadia.kaur@example.com","technicalLead":"Stephen Nkemelu","technicalLeadResourceId":"RES-0109","technicalLeadEmail":"stephen.nkemelu@example.com","businessAnalyst":"Joseph Adeyemi","businessAnalystResourceId":"RES-0113","businessAnalystEmail":"joseph.adeyemi@example.com","testLead":"Ffion Davies","testLeadResourceId":"RES-0114","testLeadEmail":"ffion.davies@example.com","changeLead":"Dominic Fry","changeLeadResourceId":"RES-0120","changeLeadEmail":"dominic.fry@example.com","financeContact":"Martin Cole","financeContactResourceId":"RES-0115","financeContactEmail":"martin.cole@example.com","complianceContact":"","complianceContactResourceId":"","complianceContactEmail":"","benefitOwner":"Nadia Kaur","benefitOwnerResourceId":"RES-0112","benefitOwnerEmail":"nadia.kaur@example.com","projectCode":"PRJ-00009","projectName":"Adviser Portal Phase 1","description":"An online portal for intermediary firms to submit and track new business, view client valuations, and manage their own firm and adviser records.","programmeId":"PRG-00002","programme":"Sales","workstream":"Sales","businessArea":"Sales","projectType":"Technology","priority":"High","projectStatus":"Active","currentStage":"Implementation","nextStage":"Hypercare","overallRag":"Green","scheduleRag":"Green","scopeRag":"Green","financialRag":"Green","resourceRag":"Green","riskRag":"Amber","deliveryConfidence":"High","baselineStartDate":"2026-03-02","baselineEndDate":"2026-10-30","forecastStartDate":"2026-03-02","forecastEndDate":"2026-10-23","targetImplementationDate":"2026-09-28","percentageComplete":88,"dateLogged":"2025-11-24","proposedStartDate":"2026-03-02","currentPosition":"Pilot with two adviser firms completed with positive feedback and eleven minor changes, nine of which are done. Go-live approved at the September governance meeting. Rollout to the remaining 38 firms starts 28 September.","nextSteps":"Complete the final two pilot changes, run the adviser onboarding webinars, and begin phased firm enablement from 28 September.","highLevelScope":"Firm and adviser registration, new business submission for ISA and investment bond, application tracking, client valuation views, commission statements, and document download.","outOfScope":"Protection products, illustrations and quotations, bulk client data upload, and any direct member access.","inScope":"All 40 intermediary firms currently on the agency register.","businessProblem":"Advisers submit business by email and post, and chase progress by phone. Onboarding a new firm takes 15 working days of manual checks, and advisers have no visibility of application status.","desiredOutcome":"Advisers self-serve submission and tracking, onboarding falls to five days, and the new business team stops rekeying applications from paper.","businessPriority":"High","strategicDriver":"Grow intermediated new business without adding operational headcount","strategicObjective":"Channel growth","additionalStakeholders":"New Business team, Compliance, the two pilot firms, and the intermediary sales managers.","fundingSource":"Change budget 2026/27","demoDataSet":"STAGE-14A"}$ppm$::jsonb
