/* --------------------------------------------------------------------------
   8. Confirmation

   Reports what landed. If a count here is zero for something that should exist,
   a parent lookup failed and the transaction should be rolled back rather than
   committed.
   -------------------------------------------------------------------------- */

do $$
declare
    v_people integer;
    v_projects integer;
    v_tasks integer;
    v_raid integer;
    v_gates integer;
    v_orphan integer;
begin
    select count(*) into v_people from public.people where legacy_payload->>'demoDataSet' = 'STAGE-14A';
    select count(*) into v_projects from public.projects where legacy_payload->>'demoDataSet' = 'STAGE-14A';
    select count(*) into v_tasks from public.project_plans where legacy_payload->>'demoDataSet' = 'STAGE-14A';
    select count(*) into v_raid from public.project_raid where legacy_payload->>'demoDataSet' = 'STAGE-14A';
    select count(*) into v_gates from public.stage_gates where legacy_payload->>'demoDataSet' = 'STAGE-14A';

    /* A demo project whose programme or manager did not resolve is a broken
       record, not a warning: the pages that join on them would show blanks. */
    select count(*) into v_orphan from public.projects
     where legacy_payload->>'demoDataSet' = 'STAGE-14A'
       and (programme_id is null or project_manager_id is null or sponsor_id is null);

    raise notice 'Stage 14A seeded: % people, % projects, % plan tasks, % RAID, % stage gates',
        v_people, v_projects, v_tasks, v_raid, v_gates;

    if v_orphan > 0 then
        raise exception '% demo project(s) failed to resolve a programme, manager or sponsor.', v_orphan;
    end if;
end $$;

commit;
